const items = $input.all();
const recipes = [];

for (const item of items) {
  const htmlContent = item.json.data;

  if (!htmlContent) continue;

  const regex = /<script type="application\/ld\+json"[^>]*>\s*([\s\S]*?)\s*<\/script>/g;
  let match;

  while ((match = regex.exec(htmlContent)) !== null) {
    try {
      const jsonData = JSON.parse(match[1]);

      let recipeData = null;

      if (jsonData['@type'] === 'Recipe') {
        recipeData = jsonData;
      } else if (jsonData['@graph']) {
        recipeData = jsonData['@graph'].find(item => item['@type'] === 'Recipe');
      }

      if (recipeData) {
        const formatted = {
          titre: recipeData.name,
          description: recipeData.description,
          categorie: recipeData.recipeCategory,
          temps_preparation: recipeData.prepTime,
          temps_cuisson: recipeData.cookTime,
          temps_total: recipeData.totalTime,
          portions: recipeData.recipeYield,
          ingredients: recipeData.recipeIngredient || [],
          etapes: (recipeData.recipeInstructions || []).map(step => 
            typeof step === 'string' ? step : (step.text || '')
          ),
          auteur: recipeData.author?.name || recipeData.author,
          image: recipeData.image?.[0] || recipeData.image,
          note: recipeData.aggregateRating ? {
            valeur: recipeData.aggregateRating.ratingValue,
            nombre_avis: recipeData.aggregateRating.reviewCount
          } : null
        };

        recipes.push(formatted);
      }
    } catch (e) {
      console.error('Erreur parsing JSON-LD:', e.message);
    }
  }
}

// Fusionner toutes les recettes en un seul item pour Ollama
return [{
  json: {
    recettes: JSON.stringify(recipes, null, 2),
    nombre_recettes: recipes.length
  }
}];

const matchedIngredients = $input.all();

function normalizeText(text) {
  if (!text) return '';

  return text
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[''`]/g, "'")
    .replace(/œ/g, 'oe')
    .replace(/æ/g, 'ae')
    .replace(/\s+/g, ' ')
    .trim();
}

function slugify(text) {
  if (!text) return '';

  return text
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/œ/g, 'oe')
    .replace(/æ/g, 'ae')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function getBaseForm(text) {
  const normalized = normalizeText(text);

  const variations = {
    'pommes de terre': 'pomme-de-terre',
    'pomme de terre': 'pomme-de-terre',
    'pdt': 'pomme-de-terre',
    'patates': 'pomme-de-terre',
    'pommes': 'pomme',
    'oeufs': 'oeuf',
    'tomates': 'tomate',
    'oignons': 'oignon',
    'gousses d\'ail': 'ail',
    'gousse d\'ail': 'ail',
    'pates': 'pate',
    'coquillettes': 'pate',
    'spaghettis': 'pate',
    'escalope de poulet': 'poulet',
    'escalopes de poulet': 'poulet',
    'filet de poulet': 'poulet',
    'filets de poulet': 'poulet',
    'blanc de poulet': 'poulet',
    'blancs de poulet': 'poulet',
    'cuisse de poulet': 'poulet',
    'cuisses de poulet': 'poulet',
    'filet de saumon': 'saumon',
    'pave de saumon': 'saumon',
    'boite de thon': 'thon',
    'fromage rape': 'fromage',
    'emmental rape': 'emmental',
    'gruyere rape': 'gruyere',
    'pain de mie': 'pain',
    'baguette': 'pain',
    'creme fraiche': 'creme',
    'creme liquide': 'creme',
    'beurre doux': 'beurre',
    'beurre demi-sel': 'beurre',
    'huile d\'olive': 'huile',
    'concentre de tomate': 'tomate',
    'tomates concassees': 'tomate',
    'coulis de tomate': 'tomate',
    'feuilles de lasagnes': 'lasagne',
    'feuilles de lasagne': 'lasagne',
    'feuilles d\'epinards': 'epinard',
    'feuilles d\'epinard': 'epinard',
    'pousses d\'epinards': 'epinard',
    'pousses d\'epinard': 'epinard',
    'feuilles de sauge': 'sauge',
    'feuilles de laurier': 'laurier'
  };

  if (variations[normalized]) {
    return variations[normalized];
  }

  let cleaned = normalized
    .replace(/^(un|une|des|du|de la|le|la|les)\s+/g, '')
    .replace(/^(feuilles?|pousses?|brins?|gousses?|tranches?)\s+(de|d')\s+/g, '')
    .replace(/\s+(de|d'|en)\s+/g, ' ')
    .replace(/\s+(frais|fraiche|rape|concasse|hache|tranche|entier|entiere)$/g, '');

  if (variations[cleaned]) {
    return variations[cleaned];
  }

  return slugify(cleaned.replace(/s$/, ''));
}

console.log('Nombre d\'items:', matchedIngredients.length);

return matchedIngredients.map(item => {
  const name = item.json.name || item.json.ingredient;
  const normalized = getBaseForm(name);

  console.log(`"${name}" → "${normalized}"`);

  return {
    json: {
      ...item.json,
      normalized_search: normalized
    }
  };
});

const ingredientItem = $input.all()[0].json;
const originalItem = $input.all()[1].json;

return [{
  json: {
    recipe_id: $('Supabase - Insert').first().json.id,  // ID de la recette
    ingredient_id: ingredientItem.id,  // ID de l'ingrédient matché
    quantity: originalItem.quantity,
    unit: originalItem.unit,
    original_ingredient: originalItem.name
  }
}];

const recipeId = $input.first().json.id;
const items = $input.all();

return items.map(item => ({
  json: {
    ...item.json,
    recipe_id: recipeId
  }
}));

let data = $input.item.json.output;

try {
  // Parse la string JSON
  if (typeof data === 'string') {
    data = JSON.parse(data);
  }

  // Vérifie que le parsing a fonctionné
  if (!data || !data.title || !data.ingredients) {
    return [{
      json: {
        error: 'Parsing failed or data incomplete',
        parsedData: data,
        originalData: $input.item.json.output
      }
    }];
  }

  return [
    {
      json: {
        type: 'recipe',
        title: data.title,
        description: data.description,
        category: data.category,
        servings: data.servings_default,
        prep_time: data.prep_time,
        cook_time: data.cook_time,
        total_time: data.minutes_total,
        difficulty: data.difficulty,
        season: data.season,
        instructions: data.instructions
      }
    },
    ...data.ingredients.map(ing => ({
      json: {
        type: 'ingredient',
        name: ing.name,
        quantity: ing.quantity,
        unit: ing.unit
      }
    }))
  ];

} catch (error) {
  return [{
    json: {
      error: error.message,
      stack: error.stack,
      originalData: $input.item.json.output
    }
  }];
}
